import React from 'react';
import { useApp } from '../context/AppContext.jsx';

function ProductCard({ product, isAdmin = false, onEdit, onDelete }) {
  const { dispatch } = useApp();

  const addToCart = () => {
    dispatch({ type: 'ADD_TO_CART', payload: product });
  };

  return (
    <div style={{
      border: '1px solid rgba(102, 126, 234, 0.2)',
      borderRadius: '16px',
      padding: '1.5rem',
      margin: '0.5rem',
      background: 'rgba(255, 255, 255, 0.95)',
      backdropFilter: 'blur(10px)',
      boxShadow: '0 8px 32px rgba(102, 126, 234, 0.15)',
      transition: 'all 0.3s ease',
      cursor: 'pointer'
    }}>
      <img 
        src={product.image} 
        alt={product.name}
        style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '12px' }}
      />
      <h3 style={{ margin: '1rem 0 0.5rem 0', color: '#1e293b', fontSize: '1.25rem', fontWeight: '600' }}>{product.name}</h3>
      <p style={{ fontSize: '1.5rem', fontWeight: '700', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', margin: '0.5rem 0' }}>
        ${product.price}
      </p>
      <p style={{ color: '#6b7280', fontSize: '0.9rem', marginBottom: '1rem' }}>Stock: {product.stock}</p>

      {isAdmin ? (
        <div style={{ display: 'flex', gap: '0.5rem', marginTop: '1rem' }}>
          <button 
            onClick={() => onEdit(product)}
            style={{
              padding: '0.75rem 1rem',
              background: 'linear-gradient(135deg, #11998e 0%, #38ef7d 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '10px',
              cursor: 'pointer',
              flex: 1,
              fontWeight: '500',
              transition: 'all 0.3s ease',
              boxShadow: '0 4px 15px rgba(17, 153, 142, 0.4)'
            }}
          >
            Editar
          </button>
          <button 
            onClick={() => onDelete(product.id)}
            style={{
              padding: '0.75rem 1rem',
              background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '10px',
              cursor: 'pointer',
              flex: 1,
              fontWeight: '500',
              transition: 'all 0.3s ease',
              boxShadow: '0 4px 15px rgba(255, 65, 108, 0.4)'
            }}
          >
            Eliminar
          </button>
        </div>
      ) : (
        <button 
          onClick={addToCart}
          disabled={product.stock === 0}
          style={{
            width: '100%',
            padding: '0.75rem',
            background: product.stock === 0 ? '#9ca3af' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: product.stock === 0 ? 'not-allowed' : 'pointer',
            marginTop: '1rem',
            fontWeight: '500',
            fontSize: '1rem',
            transition: 'all 0.3s ease',
            boxShadow: product.stock === 0 ? 'none' : '0 4px 15px rgba(102, 126, 234, 0.4)'
          }}
        >
          {product.stock === 0 ? 'Sin Stock' : 'Agregar al Carrito'}
        </button>
      )}
    </div>
  );
}

export default ProductCard;
